INSERT INTO public.schools(school_name,city,educational_level,director_user_id) SELECT 'Upside Demo Academy', 'Tunis', 'primary,high_school', user_id FROM public.users WHERE email='director@upside.example.test' AND NOT EXISTS(SELECT 1 FROM public.schools WHERE school_name='Upside Demo Academy');
INSERT INTO public.schools(school_name,city,educational_level,director_user_id) SELECT 'Second Demo School', 'Sfax', 'primary', user_id FROM public.users WHERE email='director2@upside.example.test' AND NOT EXISTS(SELECT 1 FROM public.schools WHERE school_name='Second Demo School');
INSERT INTO public.teachers(user_id,school_id,specialization) SELECT u.user_id, sc.school_id, 'Mathematics' FROM public.users u CROSS JOIN public.schools sc WHERE u.email='teacher@upside.example.test' AND sc.school_name='Upside Demo Academy' ON CONFLICT(user_id) DO NOTHING;
INSERT INTO public.teachers(user_id,school_id,specialization) SELECT u.user_id, sc.school_id, 'French' FROM public.users u CROSS JOIN public.schools sc WHERE u.email='teacher2@upside.example.test' AND sc.school_name='Second Demo School' ON CONFLICT(user_id) DO NOTHING;
INSERT INTO public.parents(user_id) SELECT user_id FROM public.users WHERE email='parent@upside.example.test' ON CONFLICT(user_id) DO NOTHING;
INSERT INTO public.parents(user_id) SELECT user_id FROM public.users WHERE email='parent2@upside.example.test' ON CONFLICT(user_id) DO NOTHING;
INSERT INTO public.classes(school_id,class_name,grade_level,academic_year,capacity) SELECT school_id,'3A','3rd primary','2026-2027',25 FROM public.schools WHERE school_name='Upside Demo Academy' ON CONFLICT(school_id,class_name,academic_year) DO NOTHING;
INSERT INTO public.classes(school_id,class_name,grade_level,academic_year,capacity) SELECT school_id,'9B','9th grade','2026-2027',25 FROM public.schools WHERE school_name='Upside Demo Academy' ON CONFLICT(school_id,class_name,academic_year) DO NOTHING;
INSERT INTO public.classes(school_id,class_name,grade_level,academic_year,capacity) SELECT school_id,'3C','3rd primary','2026-2027',25 FROM public.schools WHERE school_name='Second Demo School' ON CONFLICT(school_id,class_name,academic_year) DO NOTHING;
INSERT INTO public.students(user_id,parent_id,school_id,date_of_birth) SELECT u.user_id,p.parent_id,sc.school_id,'2017-04-12' FROM public.users u JOIN public.users pu ON pu.email='parent@upside.example.test' JOIN public.parents p ON p.user_id=pu.user_id CROSS JOIN public.schools sc WHERE u.email='junior@upside.example.test' AND sc.school_name='Upside Demo Academy' ON CONFLICT(user_id) DO NOTHING;
INSERT INTO public.students(user_id,parent_id,school_id,date_of_birth) SELECT u.user_id,p.parent_id,sc.school_id,'2011-05-08' FROM public.users u JOIN public.users pu ON pu.email='parent@upside.example.test' JOIN public.parents p ON p.user_id=pu.user_id CROSS JOIN public.schools sc WHERE u.email='senior@upside.example.test' AND sc.school_name='Upside Demo Academy' ON CONFLICT(user_id) DO NOTHING;
INSERT INTO public.students(user_id,parent_id,school_id,date_of_birth) SELECT u.user_id,p.parent_id,sc.school_id,'2016-03-09' FROM public.users u JOIN public.users pu ON pu.email='parent2@upside.example.test' JOIN public.parents p ON p.user_id=pu.user_id CROSS JOIN public.schools sc WHERE u.email='junior2@upside.example.test' AND sc.school_name='Second Demo School' ON CONFLICT(user_id) DO NOTHING;
INSERT INTO public.guardian_student_links(parent_id,student_id) SELECT s.parent_id,s.student_id FROM public.students s JOIN public.users u ON u.user_id=s.user_id WHERE u.email IN ('junior@upside.example.test','senior@upside.example.test','junior2@upside.example.test') ON CONFLICT DO NOTHING;
INSERT INTO public.student_enrollments(student_id,class_id,school_id) SELECT s.student_id,c.class_id,s.school_id FROM public.students s JOIN public.users u ON u.user_id=s.user_id JOIN public.classes c ON c.school_id=s.school_id JOIN public.schools sc ON sc.school_id=s.school_id WHERE u.email='junior@upside.example.test' AND c.class_name='3A' AND sc.school_name='Upside Demo Academy' ON CONFLICT(student_id,class_id) DO NOTHING;
INSERT INTO public.student_enrollments(student_id,class_id,school_id) SELECT s.student_id,c.class_id,s.school_id FROM public.students s JOIN public.users u ON u.user_id=s.user_id JOIN public.classes c ON c.school_id=s.school_id JOIN public.schools sc ON sc.school_id=s.school_id WHERE u.email='senior@upside.example.test' AND c.class_name='9B' AND sc.school_name='Upside Demo Academy' ON CONFLICT(student_id,class_id) DO NOTHING;
INSERT INTO public.student_enrollments(student_id,class_id,school_id) SELECT s.student_id,c.class_id,s.school_id FROM public.students s JOIN public.users u ON u.user_id=s.user_id JOIN public.classes c ON c.school_id=s.school_id JOIN public.schools sc ON sc.school_id=s.school_id WHERE u.email='junior2@upside.example.test' AND c.class_name='3C' AND sc.school_name='Second Demo School' ON CONFLICT(student_id,class_id) DO NOTHING;
INSERT INTO public.teacher_classes(teacher_id,class_id,school_id,subject_id) SELECT t.teacher_id,c.class_id,c.school_id,sj.subject_id FROM public.teachers t JOIN public.users u ON u.user_id=t.user_id JOIN public.classes c ON c.school_id=t.school_id JOIN public.subjects sj ON sj.subject_name='Mathematics' AND sj.school_level='primary' WHERE u.email='teacher@upside.example.test' AND c.class_name='3A' ON CONFLICT(teacher_id,class_id,subject_id) DO NOTHING;
INSERT INTO public.teacher_classes(teacher_id,class_id,school_id,subject_id) SELECT t.teacher_id,c.class_id,c.school_id,sj.subject_id FROM public.teachers t JOIN public.users u ON u.user_id=t.user_id JOIN public.classes c ON c.school_id=t.school_id JOIN public.subjects sj ON sj.subject_name='Mathematics' AND sj.school_level='high_school' WHERE u.email='teacher@upside.example.test' AND c.class_name='9B' ON CONFLICT(teacher_id,class_id,subject_id) DO NOTHING;
INSERT INTO public.teacher_classes(teacher_id,class_id,school_id,subject_id) SELECT t.teacher_id,c.class_id,c.school_id,sj.subject_id FROM public.teachers t JOIN public.users u ON u.user_id=t.user_id JOIN public.classes c ON c.school_id=t.school_id JOIN public.subjects sj ON sj.subject_name='Mathematics' AND sj.school_level='primary' WHERE u.email='teacher2@upside.example.test' AND c.class_name='3C' ON CONFLICT(teacher_id,class_id,subject_id) DO NOTHING;
INSERT INTO public.student_survey(student_id,school_level,grade_level,difficulty_level,consent) SELECT st.student_id,'primary','3rd primary',2,true FROM public.students st JOIN public.users u ON u.user_id=st.user_id WHERE u.email='junior@upside.example.test' ON CONFLICT(student_id) DO NOTHING;
INSERT INTO public.student_survey(student_id,school_level,grade_level,difficulty_level,consent) SELECT st.student_id,'high_school','9th grade',3,true FROM public.students st JOIN public.users u ON u.user_id=st.user_id WHERE u.email='senior@upside.example.test' ON CONFLICT(student_id) DO NOTHING;
INSERT INTO public.student_survey(student_id,school_level,grade_level,difficulty_level,consent) SELECT st.student_id,'primary','3rd primary',4,true FROM public.students st JOIN public.users u ON u.user_id=st.user_id WHERE u.email='junior2@upside.example.test' ON CONFLICT(student_id) DO NOTHING;
INSERT INTO public.student_hobbies(student_id,hobby_id) SELECT st.student_id,h.id FROM public.students st JOIN public.users u ON u.user_id=st.user_id CROSS JOIN public.hobbies h WHERE u.email='junior@upside.example.test' AND h.label IN ('Drawing / art','Sports') ON CONFLICT DO NOTHING;
INSERT INTO public.student_hobbies(student_id,hobby_id) SELECT st.student_id,h.id FROM public.students st JOIN public.users u ON u.user_id=st.user_id CROSS JOIN public.hobbies h WHERE u.email='senior@upside.example.test' AND h.label IN ('Programming','Reading') ON CONFLICT DO NOTHING;
